/* Reutiliza el logotipo oficial de Dejavú Marketing ya aprobado para los correos de ÁGORA. */
(()=>{
 const logo="data:image/png;base64,";
 function install(){
  document.querySelectorAll('.brand-glyph').forEach(holder=>{
   if(holder.querySelector('.dejavu-logo'))return;
   holder.textContent='';
   holder.classList.add('dejavu-brandmark');
   const img=document.createElement('img');
   img.src=logo;
   img.className='dejavu-logo';
   img.alt='Dejavú Marketing · Identidad oficial';
   holder.appendChild(img);
  });
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install,{once:true});else install();
})();
